// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore Generated by the OpenNext build.
import handler from "./.open-next/worker.js";

type WorkerEnv = {
  CRON_SECRET?: string;
};

type ScheduledController = {
  scheduledTime: number;
  cron: string;
};

type WorkerContext = {
  waitUntil(promise: Promise<unknown>): void;
  passThroughOnException(): void;
};

const worker = {
  fetch: handler.fetch,

  async scheduled(
    event: ScheduledController,
    env: WorkerEnv,
    context: WorkerContext,
  ) {
    if (!env.CRON_SECRET) {
      throw new Error("CRON_SECRET is not configured.");
    }

    // "40 2 * * *" is the 08:10 IST landlord summary; every other trigger bills rent.
    const path = event.cron === "40 2 * * *" ? "/api/cron/daily-summary" : "/api/cron/rent-bills";
    const response = await handler.fetch(
      new Request(`https://internal.bhada${path}`, {
        method: "POST",
        headers: {
          authorization: `Bearer ${env.CRON_SECRET}`,
          "x-scheduled-time": String(event.scheduledTime),
        },
      }),
      env,
      context,
    );

    if (!response.ok) {
      throw new Error(`Scheduled job ${path} failed with status ${response.status}.`);
    }
  },
};

export default worker;
